    "C89","C107","C70","C80"
  ],
  "claims": [
    {
      "claim": "L1 gold-context records report measured human absolute oral bioavailability values predominantly in the 50–100% range, all above the F≥20% threshold: doxazosin 62–75%, ACT-1004-1239 53%, suvorexant 82%, ofloxacin 80–95%, tegafur ~100%, nebivolol 96% in extensive metabolizers, balcinrenone 52%, dovitinib ~75%, mirtazapine ~50%, and baloxavir marboxil high.",
      "card_ids": ["C01","C04","C05","C06","C08","C09","C10","C11","C12","C15","C17","C19","C21","C22"]
    },
    {
      "claim": "L2 records from the same contexts add F values above 20% across species and formulations, including doxazosin 62–69% in humans and 24.4% in rats, dovitinib 73–77% in rat/mouse, tegafur 43.79–70.84% in dogs, and suvorexant sufficient oral bioavailability in rats, reinforcing the high direction.",
      "card_ids": ["C23","C26","C27","C40","C42","C60","C63","C64","C65"]
    },
    {
      "claim": "L3 oral exposure records include a direct oral-versus-IV comparison for tedizolid: oral AUC 26.1 vs IV 30.5 µg·h/mL and oral Cmax 2.25 vs IV 3.02 µg/mL, indicating high oral bioavailability for that reference; other L3 records show measurable oral Cmax/AUC for structurally related fluoroquinolones and heteroaromatic molecules, but most lack IV comparators and are not query-specific.",
      "card_ids": ["C89","C107","C70","C80","C68","C75","C102","C82","C98","C84","C95","C105","C77","C100","C104"]
    },
    {
      "claim": "The only sub-20% F records are nebivolol-specific (low in rats, as low as 12% in some extensive metabolizers, range 12–96%); they are not query-matched and do not provide affirmative evidence that the query has F<20%.",
      "card_ids": ["C31","C50","C52","C57"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "L3 oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": [
        "C89","C107","C70","C80","C68","C75","C102","C82","C98","C84","C95","C105",
        "C77","C100","C104","C66","C83","C88","C106","C109","C111","C114",
        "C67","C79","C87","C97","C91","C112"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct human or preclinical PK/bioavailability measurement for the query molecule.",
    "No query-specific oral AUC, Cmax, or IV-comparator data.",
    "No query-specific permeability, efflux, transporter, or first-pass metabolism data.",
    "Most L3 exposure records lack IV comparators, so absolute bioavailability cannot be derived from them.",
    "Reference contexts are structurally diverse and transfer is indirect; L3 record transfer likelihoods are moderate (~0.65–0.69).",
    "No dose, formulation, or species context is available for the query."
  ],
  "decision_summary": "L1/L2 gold-context records predominantly support F≥20%, with most measured human values in the 50–100% range. L3 adds oral exposure evidence, including a tedizolid oral-versus-IV comparison indicating high oral bioavailability and measurable oral Cmax/AUC for structurally related molecules, but no query-specific PK. The only sub-20% records are nebivolol-specific and not query-matched. The high prediction is retained and modestly strengthened; confidence remains moderate because transfer is indirect."
}

